// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address caller, uint256 amount, uint256 withdrawAmount) public {
        // Ensure caller never deposits (by bounding amount < MinDeposit)
        vm.assume(amount < c.MinDeposit());
        vm.assume(withdrawAmount > 0 && withdrawAmount <= amount);

        // Give caller some ether to deposit if they try
        vm.deal(caller, 100 ether);
        vm.prank(caller);
        c.Deposit{value: amount}();

        // Now attempt CashOut with withdrawAmount
        vm.prank(caller);
        (bool success, ) = address(c).call(abi.encodeWithSignature("CashOut(uint256)", withdrawAmount));

        // General rule: caller's balance in mapping must be 0 (since deposit never went through)
        assertTrue(c.balances(caller) == 0);

        // Ensure the call didn't revert (to avoid false positive)
        assertTrue(success);
    }
}

